```py codx/junior/team/team_manager.py
import os
import json
import pathlib
import logging
import shutil

from typing import List, Optional

from codx.junior.settings import CODXJuniorSettings
from codx.junior.model.team import Team, TeamMember

logger = logging.getLogger(__name__)


class TeamManager:
    """Manages teams, team members, and their associated profiles."""

    def __init__(self, settings: CODXJuniorSettings):
        self.settings = settings
        self.teams_path = f"{settings.codx_path}/teams"
        os.makedirs(self.teams_path, exist_ok=True)

    def get_team_path(self, team_id: str) -> str:
        """Get the directory path for a team."""
        return os.path.join(self.teams_path, team_id)

    def get_team_file_path(self, team_id: str) -> str:
        """Get the JSON file path for a team."""
        return os.path.join(self.get_team_path(team_id), f"{team_id}.team")

    def list_teams(self) -> List[Team]:
        """List all teams in the project."""
        teams = []

        if not os.path.exists(self.teams_path):
            return teams

        for item in os.listdir(self.teams_path):
            team_dir = os.path.join(self.teams_path, item)
            if os.path.isdir(team_dir):
                team_file = os.path.join(team_dir, f"{item}.team")
                if os.path.isfile(team_file):
                    team = self.load_team(team_file)
                    if team:
                        teams.append(team)

        return teams

    def load_team(self, team_file_path: str) -> Optional[Team]:
        """Load a team from a JSON file."""
        try:
            with open(team_file_path, 'r') as f:
                content = f.read()

                if not content or not content.strip():
                    logger.warning(f"Team file is empty: {team_file_path}")
                    return None

                team = Team(**json.loads(content))
                team.project_id = self.settings.project_id
                return team
        except Exception as ex:
            logger.exception(f"Error loading team from {team_file_path}: {ex}")
            return None

    def create_team(self, team: Team) -> Team:
        """Create a new team."""
        if not team.name:
            raise ValueError("Team name is required")

        team_dir = self.get_team_path(team.team_id)
        os.makedirs(team_dir, exist_ok=True)

        team.project_id = self.settings.project_id
        self.save_team(team)

        logger.info(f"Created team: {team.team_id} - {team.name}")
        return team

    def save_team(self, team: Team) -> Team:
        """Save team to file."""
        if not team.name:
            raise ValueError("Team name is required")

        team_dir = self.get_team_path(team.team_id)
        os.makedirs(team_dir, exist_ok=True)

        team_file = self.get_team_file_path(team.team_id)

        # Update timestamp
        team.updated_at = __import__('datetime').datetime.utcnow().isoformat()

        with open(team_file, 'w') as f:
            f.write(json.dumps(team.model_dump(), indent=2))

        logger.info(f"Saved team: {team.team_id}")
        return team

    def get_team(self, team_id: str) -> Optional[Team]:
        """Get a team by ID."""
        team_file = self.get_team_file_path(team_id)
        if os.path.isfile(team_file):
            return self.load_team(team_file)
        return None

    def delete_team(self, team_id: str) -> bool:
        """Delete a team and its directory."""
        team_dir = self.get_team_path(team_id)
        if os.path.isdir(team_dir):
            shutil.rmtree(team_dir)
            logger.info(f"Deleted team: {team_id}")
            return True
        return False

    def add_team_member(self, team_id: str, username: str, role: str = "member") -> Optional[Team]:
        """Add a member to a team."""
        team = self.get_team(team_id)
        if not team:
            return None

        # Check if member already exists
        if any(m.username == username for m in team.members):
            logger.warning(f"User {username} is already a member of team {team_id}")
            return team

        member = TeamMember(username=username, role=role)
        team.members.append(member)

        return self.save_team(team)

    def remove_team_member(self, team_id: str, username: str) -> Optional[Team]:
        """Remove a member from a team."""
        team = self.get_team(team_id)
        if not team:
            return None

        team.members = [m for m in team.members if m.username != username]

        return self.save_team(team)

    def update_member_role(self, team_id: str, username: str, role: str) -> Optional[Team]:
        """Update a member's role in a team."""
        team = self.get_team(team_id)
        if not team:
            return None

        for member in team.members:
            if member.username == username:
                member.role = role
                break

        return self.save_team(team)

    def add_profile_to_team(self, team_id: str, profile_name: str) -> Optional[Team]:
        """Add a profile to a team."""
        team = self.get_team(team_id)
        if not team:
            return None

        if profile_name not in team.profiles:
            team.profiles.append(profile_name)

        return self.save_team(team)

    def remove_profile_from_team(self, team_id: str, profile_name: str) -> Optional[Team]:
        """Remove a profile from a team."""
        team = self.get_team(team_id)
        if not team:
            return None

        team.profiles = [p for p in team.profiles if p != profile_name]

        return self.save_team(team)

    def get_user_teams(self, username: str) -> List[Team]:
        """Get all teams that a user is a member of."""
        all_teams = self.list_teams()
        return [team for team in all_teams if any(m.username == username for m in team.members)]

    def get_team_members(self, team_id: str) -> List[TeamMember]:
        """Get all members of a team."""
        team = self.get_team(team_id)
        return team.members if team else []
