```py codx/junior/api/teams.py
import logging
from fastapi import APIRouter, Request, Depends, HTTPException
from datetime import datetime

from codx.junior.engine import CODXJuniorSession
from codx.junior.security.user_management import get_authenticated_user
from codx.junior.model.model import CodxUser
from codx.junior.model.team import Team, TeamMember
from codx.junior.team.team_manager import TeamManager

logger = logging.getLogger(__name__)

router = APIRouter()


@router.get("/teams")
def list_teams(request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """List all teams in the project."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)
        teams = team_manager.list_teams()
        return {"teams": teams, "count": len(teams)}
    except Exception as ex:
        logger.error(f"Error listing teams: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.get("/teams/{team_id}")
def get_team(team_id: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Get a specific team by ID."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)
        team = team_manager.get_team(team_id)

        if not team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error getting team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.post("/teams")
def create_team(team: Team, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Create a new team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        # Add creator as owner
        creator_member = TeamMember(username=user.username, role="owner")
        if not any(m.username == user.username for m in team.members):
            team.members.append(creator_member)

        created_team = team_manager.create_team(team)
        return created_team
    except ValueError as ex:
        logger.error(f"Validation error creating team: {ex}")
        raise HTTPException(status_code=400, detail=str(ex))
    except Exception as ex:
        logger.error(f"Error creating team: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.put("/teams/{team_id}")
def update_team(team_id: str, team_update: Team, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Update a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        existing_team = team_manager.get_team(team_id)
        if not existing_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        # Preserve team_id and created_at
        team_update.team_id = team_id
        team_update.created_at = existing_team.created_at

        updated_team = team_manager.save_team(team_update)
        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error updating team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.delete("/teams/{team_id}")
def delete_team(team_id: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Delete a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        if team_manager.delete_team(team_id):
            return {"status": "deleted", "team_id": team_id}
        else:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error deleting team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.post("/teams/{team_id}/members")
def add_team_member(team_id: str, member: TeamMember, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Add a member to a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        updated_team = team_manager.add_team_member(
            team_id=team_id,
            username=member.username,
            role=member.role
        )

        if not updated_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error adding member to team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.delete("/teams/{team_id}/members/{username}")
def remove_team_member(team_id: str, username: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Remove a member from a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        updated_team = team_manager.remove_team_member(team_id=team_id, username=username)

        if not updated_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error removing member from team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.put("/teams/{team_id}/members/{username}/role")
def update_member_role(team_id: str, username: str, role_data: dict, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Update a member's role in a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        role = role_data.get("role")
        if not role:
            raise HTTPException(status_code=400, detail="Role is required")

        updated_team = team_manager.update_member_role(
            team_id=team_id,
            username=username,
            role=role
        )

        if not updated_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error updating member role in team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.post("/teams/{team_id}/profiles/{profile_name}")
def add_profile_to_team(team_id: str, profile_name: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Add a profile to a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        updated_team = team_manager.add_profile_to_team(team_id=team_id, profile_name=profile_name)

        if not updated_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error adding profile to team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.delete("/teams/{team_id}/profiles/{profile_name}")
def remove_profile_from_team(team_id: str, profile_name: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Remove a profile from a team."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        updated_team = team_manager.remove_profile_from_team(team_id=team_id, profile_name=profile_name)

        if not updated_team:
            raise HTTPException(status_code=404, detail=f"Team {team_id} not found")

        return updated_team
    except HTTPException:
        raise
    except Exception as ex:
        logger.error(f"Error removing profile from team {team_id}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.get("/teams/user/{username}")
def get_user_teams(username: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Get all teams that a user is a member of."""
    try:
        codx_junior_session: CODXJuniorSession = request.state.codx_junior_session
        team_manager = TeamManager(settings=codx_junior_session.settings)

        teams = team_manager.get_user_teams(username=username)
        return {"teams": teams, "count": len(teams)}
    except Exception as ex:
        logger.error(f"Error getting teams for user {username}: {ex}")
        raise HTTPException(status_code=500, detail=str(ex))


@router.get("/teams/{team_id}/members")
def get_team_members(team_id: str, request: Request, user: CodxUser = Depends(get_authenticated_user)):
    """Get all members of a team."""
    try:
